export function translate(text: string, locale: Locale): string {
  const exact = copy[locale][text];
  if (exact !== undefined || locale === "en") return exact ?? text;
  // Many UI labels contain a live count or user/job data around a static phrase.
  // Translate known whole words/phrases inside those strings without touching
  // proper names and technical terms that have no catalog entry.
  let result = text;
  const entries = Object.entries(copy.ar)
    .filter(([source]) => source.length >= 5 && /\s/.test(source) && /[A-Za-z]/.test(source))
    .sort(([a], [b]) => b.length - a.length);
  for (const [source, target] of entries) {
    const escaped = source.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    result = result.replace(new RegExp(`\\b${escaped}\\b`, "gi"), target);
  }
  return result;
}

export function localeFromStorage(): Locale {
  if (typeof window === "undefined") return "en";
  return localStorage.getItem("qaddemni-locale") === "ar" ? "ar" : "en";
}

export function applyLocale(locale: Locale) {
  if (typeof document === "undefined") return;
  document.documentElement.lang = locale;
  document.documentElement.dir = locale === "ar" ? "rtl" : "ltr";
  document.documentElement.dataset.locale = locale;
}
